ALTER TABLE public.contracts ADD COLUMN billing_enabled boolean NOT NULL DEFAULT false, ADD COLUMN billing_enabled_at timestamptz, ADD COLUMN billing_lines jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.invoices ADD COLUMN contract_id uuid REFERENCES public.contracts(id), ADD COLUMN contract_reference text, ADD COLUMN auto_send_started_at timestamptz;
CREATE UNIQUE INDEX invoice_contract_completion_unique ON public.invoices(work_order_id) WHERE contract_id IS NOT NULL AND kind = 'factuur';
CREATE TABLE public.contract_billing_queue (work_order_id uuid PRIMARY KEY REFERENCES public.work_orders(id) ON DELETE CASCADE, contract_id uuid NOT NULL REFERENCES public.contracts(id), invoice_id uuid REFERENCES public.invoices(id), status text NOT NULL DEFAULT 'pending', error text, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.contract_billing_queue TO authenticated;
GRANT ALL ON public.contract_billing_queue TO service_role;
ALTER TABLE public.contract_billing_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read contract billing" ON public.contract_billing_queue FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.track_contract_billing_activation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.billing_enabled AND NOT OLD.billing_enabled THEN NEW.billing_enabled_at=now(); ELSIF NOT NEW.billing_enabled THEN NEW.billing_enabled_at=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER contract_billing_activation BEFORE UPDATE ON public.contracts FOR EACH ROW EXECUTE FUNCTION public.track_contract_billing_activation();
CREATE FUNCTION public.queue_completed_contract_billing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='afgetekend' AND OLD.status IS DISTINCT FROM 'afgetekend' AND NEW.contract_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.contracts c WHERE c.id=NEW.contract_id AND c.active AND c.billing_enabled AND c.billing_enabled_at IS NOT NULL AND c.billing_enabled_at <= now()) THEN INSERT INTO public.contract_billing_queue(work_order_id,contract_id) VALUES(NEW.id,NEW.contract_id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER completed_contract_billing AFTER UPDATE ON public.work_orders FOR EACH ROW EXECUTE FUNCTION public.queue_completed_contract_billing();
CREATE FUNCTION public.create_contract_completion_invoice(p_work_order uuid,p_customer jsonb,p_lines jsonb,p_net numeric,p_vat numeric,p_total numeric,p_vat_rate numeric,p_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.contract_billing_queue; result uuid; issue date=(now() AT TIME ZONE 'Europe/Brussels')::date; BEGIN SELECT * INTO q FROM public.contract_billing_queue WHERE work_order_id=p_work_order FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No queued completion'; END IF; SELECT id INTO result FROM public.invoices WHERE work_order_id=p_work_order AND contract_id IS NOT NULL AND kind='factuur'; IF result IS NULL THEN INSERT INTO public.invoices(number,work_order_id,contract_id,contract_reference,issue_date,due_date,customer,lines,vat_rate,net,vat,total,paid_amount) VALUES(public.next_invoice_number(),p_work_order,q.contract_id,p_reference,issue,issue+(SELECT payment_days FROM public.settings WHERE id=1),p_customer,p_lines,p_vat_rate,p_net,p_vat,p_total,0) RETURNING id INTO result; END IF; UPDATE public.contract_billing_queue SET invoice_id=result,status='created',updated_at=now() WHERE work_order_id=p_work_order; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_contract_completion_invoice(uuid,jsonb,jsonb,numeric,numeric,numeric,numeric,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_contract_completion_invoice(uuid,jsonb,jsonb,numeric,numeric,numeric,numeric,text) TO service_role;